package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"

	"github.com/avroschema/go-avro"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <source_file> <struct_name>")
		return
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Load the source code
	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Printf("Error reading source file: %v\n", err)
		return
	}

	// Parse the struct definition
	typeDefinition, err := parseStruct(content, structName)
	if err != nil {
		fmt.Printf("Failed to parse struct definition: %v\n", err)
		return
	}

	// Generate the Avro schema
	schema, err := typeDefinition.ToAvroSchema()
	if err != nil {
		fmt.Printf("Failed to convert struct to Avro schema: %v\n", err)
		return
	}

	// Write the generated schema to a file
	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), []byte(schema), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema to file: %v\n", err)
	}
}

// parseStruct parses the provided Go source content and extracts the struct definition.
func parseStruct(code []byte, typeName string) (*avro.TypeDefinition, error) {
	var structDef avro.StructTypeDefinition
	err := json.Unmarshal(code, &structDef)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal struct definition: %w", err)
	}

	// Ensure the struct has exactly one field with the specified name
	for _, field := range structDef.Fields() {
		if field.Name == typeName {
			return &avro.TypeDefinition{Field: field}, nil
		}
	}

	return nil, fmt.Errorf("struct '%s' not found", typeName)
}
```

